from email.message import EmailMessage
import smtplib

def send_notification(host,port,to,subject,body,recovered=False):
    if host!='127.0.0.1' or isinstance(port,bool) or not isinstance(port,int) or not 1<=port<=65535:raise ValueError('loopback SMTP fixture only')
    if not isinstance(to,str) or '@' not in to or any(c in to for c in '\r\n'):raise ValueError('invalid recipient')
    if not isinstance(subject,str) or not subject or any(c in subject for c in '\r\n'):raise ValueError('invalid subject')
    if not isinstance(body,str) or not body:raise ValueError('body required')
    msg=EmailMessage();msg['From']='alerts@example.invalid';msg['To']=to;msg['Subject']=subject
    msg['X-Alert-State']='resolved' if recovered else 'firing'
    msg.set_content(body,subtype='plain',charset='utf-8')
    with smtplib.SMTP(host,port,timeout=2) as client:client.send_message(msg)
    return True
